from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from push_notifications.models import APNSDevice

class APNSDeviceDeregisterView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request):
        token_hex = request.data.get("registration_id")
        # Require that the device being deleted is registered to request.user
        deleted, _ = APNSDevice.objects.filter(
            registration_id=token_hex,
            user=request.user
        ).delete()
        if not deleted:
            return Response({"error": "Device registration not found or unauthorized"}, status=status.HTTP_404_NOT_FOUND)

        return Response({"status": "Device unregistered successfully"}, status=status.HTTP_200_OK)
